const char * frontend_parse_match_expr_type_key_text(const char * in) {
    const char * k;
    k = frontend_type_type_key_text(in);
    if ((!k)) {
        return (const char *)(0);
    }
    if (strncmp(k, "struct", 6) == 0) {
        k += 6;
    }
    else {
        if (strncmp(k, "union", 5) == 0) {
            k += 5;
        }
        else {
            if (strncmp(k, "enum", 4) == 0) {
                k += 4;
            }
        }
    }
    return runtime_text_ct_intern(k);
}
